"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81412"],{89788(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.notas_do_enem.inscricoes_em_andamento","status":422,"titulo":"As inscri\xe7\xf5es do processo ainda n\xe3o terminaram"},"descricao":{"codigo":"uniplus.selecao.notas_do_enem.inscricoes_em_andamento","requisitos":[],"oQueAconteceu":["O arquivo enviado ao INEP e a importa\xe7\xe3o do retorno s\xf3 fazem sentido com o\\nconjunto de inscritos fechado: antes do encerramento, o envio sairia incompleto,\\ne a importa\xe7\xe3o casaria notas com inscri\xe7\xf5es que ainda podem mudar. Por isso a\\ngera\xe7\xe3o do envio e a importa\xe7\xe3o do lote de notas s\xe3o recusadas enquanto o\\nper\xedodo de inscri\xe7\xe3o do processo n\xe3o terminou.","O per\xedodo \xe9 o da vers\xe3o divulgada do edital, a mesma que o candidato v\xea. Se uma\\nretifica\xe7\xe3o divulgada prorrogou o fim das inscri\xe7\xf5es, vale o novo fim. O \xfaltimo\\ninstante do per\xedodo ainda conta como inscri\xe7\xe3o aberta; s\xf3 depois dele as duas\\nopera\xe7\xf5es s\xe3o aceitas. A mensagem informa a data e a hora do fim, no hor\xe1rio de\\nBel\xe9m (PA)."],"comoResolver":["Aguarde o encerramento do per\xedodo de inscri\xe7\xe3o e repita a opera\xe7\xe3o depois dele.\\nNada foi gerado nem importado na tentativa recusada."],"ondeAparece":["Gera\xe7\xe3o do arquivo de envio ao INEP","Importa\xe7\xe3o do arquivo de retorno do INEP"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Notas do enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);